tap='(async()=>{const f=window.__BUBBLE_KEEP_FIXTURE__,wait=ms=>new Promise(r=>setTimeout(r,ms)),fire=b=>{const q=b.getBoundingClientRect(),o={bubbles:true,cancelable:true,pointerId:81,pointerType:"touch",isPrimary:true,button:0,clientX:q.left+q.width/2,clientY:q.top+q.height/2};b.dispatchEvent(new PointerEvent("pointerdown",o));b.dispatchEvent(new PointerEvent("pointerup",o));b.dispatchEvent(new MouseEvent("click",{bubbles:true,cancelable:true,detail:1,clientX:o.clientX,clientY:o.clientY}))},trace=[];for(const b of f.api.elements.buttons.filter(x=>x.dataset.shape==="round")){fire(b);const during=f.api.inspect();await wait(f.motion==="reduced"?95:175);trace.push({during,after:f.api.inspect()})}await wait(220);const report=f.report();return{status:report.status,variant:f.variant,motion:f.motion,trace,after:f.api.inspect(),runtime:f.runtime.inspect(),finishes:report.finishes,targets:report.targets,overflow:report.viewport.bodyScrollWidth>report.width,external:report.external,errors:report.errors}})()';for v in "${variants[@]}";do for m in "${motions[@]}";do nav "$v" initial "$m" 390 844 1;node tools/qa-browser-lanes.mjs eval audit "$tap" >"$OUT/touch-success-$v-$m.json";node tools/qa-browser-lanes.mjs screenshot audit "$OUT/touch-success-$v-$m.png" >/dev/null;done;done
