deadline='(async()=>{const f=window.__BUBBLE_KEEP_FIXTURE__,wait=ms=>new Promise(r=>setTimeout(r,ms));f.api.showScene("meter-2");const before=f.api.inspect();for(let i=0;i<200;i++){if(f.report().finishes.length)break;await wait(100)}const elapsed=performance.now()-f.renderedAt,report=f.report();return{motion:f.motion,elapsed,before,after:f.api.inspect(),runtime:f.runtime.inspect(),finishes:report.finishes,overflow:report.viewport.bodyScrollWidth>report.width,external:report.external,errors:report.errors}})()';nav 1 initial normal 390 844 1;node tools/qa-browser-lanes.mjs eval audit "$deadline" >"$OUT/deadline-390x844-normal.json";node tools/qa-browser-lanes.mjs screenshot audit "$OUT/deadline-390x844-normal.png" >/dev/null;nav 1 initial reduced 430 932 1;node tools/qa-browser-lanes.mjs eval audit "$deadline" >"$OUT/deadline-430x932-reduced.json";node tools/qa-browser-lanes.mjs screenshot audit "$OUT/deadline-430x932-reduced.png" >/dev/null
