perf='(async()=>{const f=window.__BUBBLE_KEEP_FIXTURE__,round=f.api.elements.buttons.find(b=>b.dataset.shape==="round"),d=[];round.click();const ownedAtStart=f.runtime.inspect().frames;let p=performance.now();await new Promise(resolve=>{const tick=n=>{d.push(n-p);p=n;if(d.length===90)resolve();else requestAnimationFrame(tick)};requestAnimationFrame(tick)});const report=f.report(),runtime=f.runtime.inspect(),expected=f.motion==="normal"?1:0,result={status:d.length===90&&ownedAtStart===expected&&runtime.frames===0&&!report.external.length&&!report.errors.length&&report.viewport.bodyScrollWidth<=report.width?"pass":"fail",motion:f.motion,frames:d.length,averageFrameMs:d.reduce((a,b)=>a+b,0)/d.length,maxFrameMs:Math.max(...d),ownedAtStart,gameOwnedFramesAfter:runtime.frames,state:f.api.inspect(),runtime,overflow:report.viewport.bodyScrollWidth>report.width,external:report.external,errors:report.errors};f.runtime.dispose();return result})()';nav 0 initial normal 390 844 1;node tools/qa-browser-lanes.mjs eval audit "$perf" >"$OUT/performance-390x844-normal.json";nav 3 initial reduced 430 932 1;node tools/qa-browser-lanes.mjs eval audit "$perf" >"$OUT/performance-430x932-reduced.json"
