from pathlib import Path
from PIL import Image,ImageChops,ImageStat
import json,math,os,subprocess
r=Path(os.environ['OUT']);variants=range(4);metrics=['393x852','402x874'];motions=['normal','reduced'];scenes=['initial','round-pop','partial','meter-1','meter-2','success','exhausted','timeout'];rows=[];fail=[]
for v in variants:
 for metric in metrics:
  for scene in scenes:
