   for m in motions:
    e=json.loads((r/f'evidence-{v}-{metric}-{scene}-{m}.json').read_text());s=e['state'];ok=(scene!='initial' or len(s['tappedRoundIds'])==0 and s['starTaps']==0) and (scene!='round-pop' or s['popping'] is not None and s['popState']==1) and (scene!='partial' or len(s['tappedRoundIds'])==2 and not s['done']) and (scene!='meter-1' or s['starTaps']==1 and not s['done']) and (scene!='meter-2' or s['starTaps']==2 and not s['done']) and (scene!='success' or s['result']=='success' and len(s['remainingRoundIds'])==0) and (scene!='exhausted' or s['result']=='exhausted' and s['starTaps']==3) and (scene!='timeout' or s['result']=='timeout')
