for m in motions:
 e=json.loads((r/f'recover-success-{m}.json').read_text())
 if not(e['one']['starTaps']==1 and not e['one']['done'] and e['two']['starTaps']==2 and not e['two']['done'] and e['after']['result']=='success' and e['after']['starTaps']==2 and len(e['finishes'])==1):fail.append(f'recover {m}')
 e=json.loads((r/f'exhaust-{m}.json').read_text())
 if not(e['after']['result']=='exhausted' and e['after']['starTaps']==3 and len(e['finishes'])==1 and not e['finishes'][0]['correct']):fail.append(f'exhaust {m}')
for metric,m in [('390x844','normal'),('430x932','reduced')]:
 e=json.loads((r/f'deadline-{metric}-{m}.json').read_text())
 if not(17750<=e['elapsed']<=18550 and e['after']['result']=='timeout' and e['before']['tappedRoundIds']==e['after']['tappedRoundIds'] and e['before']['remainingRoundIds']==e['after']['remainingRoundIds'] and e['before']['starTaps']==e['after']['starTaps'] and len(e['finishes'])==1):fail.append(f'deadline {metric} {m}')
 e=json.loads((r/f'dispose-{metric}-{m}.json').read_text())
 if not(e['after']['disposed'] and e['after']['timeouts']==0 and e['after']['frames']==0 and e['after']['listeners']==0 and not e['qaPresent'] and not e['finishes']):fail.append(f'dispose {metric} {m}')
 e=json.loads((r/f'performance-{metric}-{m}.json').read_text())
 if not(e['status']=='pass' and e['frames']==90 and e['ownedAtStart']==(1 if m=='normal' else 0) and e['gameOwnedFramesAfter']==0 and not e['overflow'] and not e['errors']):fail.append(f'perf {metric} {m}')
for metric in ['390x844','430x932']:
 w,h=map(int,metric.split('x'))
 for v in variants:
  for m in motions:
   for s in ['initial','success']:
    e=json.loads((r/f'boundary-{v}-{metric}-{s}-{m}.json').read_text());im=Image.open(r/f'boundary-board{v}-{metric}-{s}-{m}.png')
    if e['status']!='pass' or e['dpr']!=3 or e['errors'] or e['external'] or e['viewport']['bodyScrollWidth']>w or min(min(t['height'],t['width']) for t in e['targets'])<44 or im.size!=(w*3,h*3):fail.append(f'boundary {v} {metric} {s} {m}')
for v in variants:
 for metric in metrics:
  for m in motions:
   e=json.loads((r/f'focus-{v}-{metric}-{m}.json').read_text())
   if not e['focused'] or e['report']['status']!='pass':fail.append(f'focus {v} {metric} {m}')
files=[str(r/f'board0-393x852-{s}-normal.png') for s in scenes];subprocess.run(['magick','montage',*files,'-thumbnail','393x852','-tile','8x1','-geometry','+4+0',str(r/'director-contact-sheet.png')],check=True)
report={'status':'pass' if not fail else 'fail','canonicalViewports':[{'width':393,'height':852,'dpr':3},{'width':402,'height':874,'dpr':3}],'variants':list(variants),'states':scenes,'comparisons':len(rows),'canonicalScreenshots':len(rows)*2,'focusScreenshots':16,'boundaryScreenshots':32,'touchRoutes':8,'keyboardRoutes':2,'recoverRoutes':2,'exhaustionRoutes':2,'allDpr3':not any('evidence' in x for x in fail),'allFullResolution':all(x['size'] in ([1179,2556],[1206,2622]) for x in rows),'maxMAE':max(x['mae'] for x in rows),'maxNormalizedRMSE':max(x['normalizedRMSE'] for x in rows),'failures':fail,'rows':rows};(r/'comparison-report.json').write_text(json.dumps(report,indent=2));print(json.dumps({k:v for k,v in report.items() if k!='rows'},indent=2));raise SystemExit(bool(fail))
PY
